import math

def max_independent_set_path(n):
    """Calculates the maximum size of an independent set in P_n."""
    if n <= 0:
        return 0
    return math.ceil(n / 2)

for n in range(1, 11):
    size = max_independent_set_path(n)
    print(f"n={n}: Max IS size = {size}")

def simulate_game(n):
    S_A = set()
    S_B = set()
    moves = 0
    turn = 0  # 0 for Alice, 1 for Bob

    while True:
        # Check for Draw condition
        chosen_count = len(S_A) + len(S_B)
        if chosen_count == n:
            return "Draw", moves

        current_player_set = S_A if turn == 0 else S_B

        # Identify available moves
        available = [i for i in range(1, n + 1) if i not in S_A and i not in S_B]

        if not available:
            # Should have been caught by chosen_count == n unless n=0, but safer check.
            return "Draw", moves

        # Determine valid moves for the current player
        valid_moves = []
        for k in available:
            is_valid = True
            # Rule (ii): Cannot choose a number consecutive to any number the player has already chosen.
            for p in current_player_set:
                if abs(k - p) == 1:
                    is_valid = False
                    break
            if is_valid:
                valid_moves.append(k)

        if not valid_moves:
            # Current player cannot move and numbers remain -> Current player loses
            if turn == 0:
                return "Bob wins", moves
            else:
                return "Alice wins", moves

        # Deterministic Strategy: Choose the smallest valid number
        next_move = min(valid_moves)

        if turn == 0:
            S_A.add(next_move)
        else:
            S_B.add(next_move)

        moves += 1
        turn = 1 - turn

# Simulate for n=1 to n=10
results = {}
for n in range(1, 11):
    outcome, moves = simulate_game(n)
    results[n] = (outcome, moves)

# Print results in a readable format
print("N | Outcome | Moves")
print("-" * 25)
for n in range(1, 11):
    outcome, moves = results[n]
    print(f"{n:<2} | {outcome:<7} | {moves}")

